from __future__ import annotations

import errno
import functools
import http.server
import json
import os
import queue
import socket
import socketserver
import ssl
import sys
import threading
import traceback
from pathlib import Path
from typing import Callable


class ServeError(Exception):
    """A dev server couldn't start. Carries an actionable message for the CLI to
    print instead of a raw traceback."""


class _QuietDisconnectServer:
    """Swallow the noisy tracebacks a browser triggers by dropping a
    connection mid-response — a TLS preconnect it never uses (``SSLEOFError:
    EOF occurred in violation of protocol``), a reset, a broken pipe. The
    server already survives these (each request is handled and torn down on
    its own); only the per-disconnect traceback is the problem. A genuine
    handler bug is any *other* exception, and still prints in full."""

    #: ConnectionError covers reset / aborted / broken-pipe; ssl.SSLError
    #: covers the TLS-EOF a client causes by closing mid-handshake/response.
    _BENIGN_DISCONNECT = (ConnectionError, ssl.SSLError, socket.timeout)

    def handle_error(self, request, client_address):
        exc = sys.exc_info()[1]
        if isinstance(exc, self._BENIGN_DISCONNECT):
            return                       # normal client hangup — stay quiet
        super().handle_error(request, client_address)


class _ReusingTCPServer(_QuietDisconnectServer, socketserver.TCPServer):
    allow_reuse_address = True


class _ReloadTCPServer(_QuietDisconnectServer,
                       socketserver.ThreadingTCPServer):
    """ThreadingTCPServer so SSE connections don't block static-file requests."""

    allow_reuse_address = True
    daemon_threads = True


#: The peers a server that speaks TLS answers: this computer, by the
#: loopback address of either family, or IPv4's as a v6 socket shows it.
#: Exactly these. A kernel never takes a loopback source address in from a
#: network interface, so no other computer can be one of them.
LOOPBACK_PEERS = frozenset({"127.0.0.1", "::1", "::ffff:127.0.0.1"})

#: Seconds a peer that passed the check has to finish its TLS handshake.
TLS_HANDSHAKE_TIMEOUT = 10


class LoopbackTLSServer(_ReloadTCPServer):
    """A server that speaks TLS, and only to this computer.

    A dev page (``serve --fake-cloud``) is served at
    ``https://<namespace>.dev.workpeg.com``, so the browser hands whatever
    answers there the visitor's whole Workpeg session. A colleague's phone that maps the name to
    this computer must get nothing.

    So the listening socket is never wrapped. Wrapped, its ``accept()`` would
    run each handshake itself, before anything could look at the peer, and a
    peer that never finished would stall every connection after it. Each
    connection is accepted raw and its peer checked first. One that is not in
    :data:`LOOPBACK_PEERS` is closed with nothing written: no ServerHello, no
    certificate. Only then is the socket wrapped, and its handshake run, in
    the connection's own thread with :data:`TLS_HANDSHAKE_TIMEOUT`.

    Nothing turns the check off: no argument, no flag, no environment
    variable. It does not stop a developer, who can change their own copy of
    the SDK; it stops another computer being answered by accident.
    """

    def __init__(self, server_address, handler, tls: ssl.SSLContext) -> None:
        self.tls = tls
        super().__init__(server_address, handler)

    def handle_error(self, request, client_address) -> None:
        # The browser sends this server the visitor's session cookies, and
        # an error's words can quote the request that caused it. So a real
        # failure is reported by its type and where it happened, never by
        # what it said, and a hang-up stays quiet as it does elsewhere.
        error = sys.exc_info()[1]
        if error is None or isinstance(error, self._BENIGN_DISCONNECT):
            return
        sys.stderr.write(
            f"workpeg: answering a request failed with "
            f"{type(error).__qualname__}. What it said is left out, because "
            f"it can quote the request's cookies.\n"
            "Traceback (most recent call last):\n"
            + "".join(traceback.format_tb(error.__traceback__)))

    def verify_request(self, request, client_address) -> bool:
        # The raw socket, before any TLS byte, in the thread that accepts.
        # Refused, socketserver closes it and nothing is sent.
        try:
            peer = request.getpeername()
        except OSError:
            return False                  # gone already
        return peer[0] in LOOPBACK_PEERS

    def finish_request(self, request, client_address) -> None:
        # In the connection's own thread, so a slow handshake holds up
        # nobody else, and under a limit, so it cannot hold this thread.
        # Wrapping runs the handshake; one that fails or runs out of time
        # raises, and handle_error stays quiet about a hang-up.
        waited = request.gettimeout()
        request.settimeout(TLS_HANDSHAKE_TIMEOUT)
        conn = self.tls.wrap_socket(request, server_side=True)
        try:
            # The limit is the handshake's alone: a browser may open a
            # connection and send its request on it later.
            conn.settimeout(waited)
            super().finish_request(conn, client_address)
        finally:
            self.shutdown_request(conn)


def _tls_context(cert: str, key: str) -> ssl.SSLContext:
    """The server side of TLS, loaded before anything is bound, so a pair
    that will not load stops the start rather than the first request."""
    context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
    context.load_cert_chain(cert, key)
    return context


def _server_class(base: type, tls: "ssl.SSLContext | None"):
    """*base* for plain HTTP, or :class:`LoopbackTLSServer` with *tls*: a
    server here speaks TLS only behind the peer check."""
    if tls is None:
        return base
    return functools.partial(LoopbackTLSServer, tls=tls)


class _SilentHandler(http.server.SimpleHTTPRequestHandler):
    """SimpleHTTPRequestHandler that suppresses per-request log lines."""

    def log_message(self, format: str, *args: object) -> None:
        pass

    def end_headers(self) -> None:
        # The bundled icon stylesheet is ~27 MB and content-addressed (its
        # link carries a hash of its own bytes), so tell the browser to keep
        # it: without this the dev server sends no caching headers and every
        # live-reload refetches the whole file, dwarfing the rebuild itself.
        # getattr: an error the standard library answers before it has a
        # path (a request line too long, or with a fourth word) has none.
        if getattr(self, "path", "").split("?")[0] == "/icons.css":
            self.send_header(
                "Cache-Control", "public, max-age=31536000, immutable")
        super().end_headers()


# The dev script: what `workpeg ui serve` adds to a page when live-reload is
# active. Served from memory at _RELOAD_SCRIPT_PATH, by _RELOAD_TAG before
# </body>, and never written into a built dist/. A file rather than an inline
# <script> because the page carries the same script policy in dev as it does
# released (build.SCRIPT_POLICY): an inline script would be refused, and a dev
# loop that needed a looser policy would hide what a release does. Provides:
#   1. Live reload over SSE (/_workpeg_reload).
#   2. An error overlay: compile errors pushed by the dev server, plus
#      uncaught runtime errors, unhandled promise rejections, and
#      console.error calls in the browser.
_RELOAD_SCRIPT_PATH = "/_workpeg_reload.js"
_RELOAD_TAG = f'<script src="{_RELOAD_SCRIPT_PATH}"></script>'.encode()
_RELOAD_SCRIPT = b"""\
/* Workpeg dev: live-reload + error overlay */
(function () {
  var overlay = null;
  var list = null;

  function ensureOverlay() {
    if (overlay) return;
    overlay = document.createElement("div");
    overlay.id = "_workpeg-error-overlay";
    overlay.style.cssText =
      "position:fixed;top:0;left:0;right:0;bottom:0;" +
      "background:rgba(0,0,0,.55);z-index:2147483647;" +
      "display:flex;align-items:center;justify-content:center;";
    var modal = document.createElement("div");
    modal.style.cssText =
      "font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;" +
      "background:#1c1c1e;color:#f2f2f2;max-width:90vw;width:680px;" +
      "max-height:80vh;overflow:auto;border-radius:8px;" +
      "border-top:3px solid #e5484d;padding:14px 18px;" +
      "box-shadow:0 12px 40px rgba(0,0,0,.5);";
    var head = document.createElement("div");
    head.style.cssText =
      "display:flex;justify-content:space-between;align-items:center;";
    var title = document.createElement("strong");
    title.textContent = "Workpeg errors";
    title.style.color = "#e5484d";
    var close = document.createElement("button");
    close.textContent = "\\u00d7";
    close.setAttribute("aria-label", "Dismiss");
    close.style.cssText =
      "background:none;border:none;color:#f2f2f2;" +
      "font-size:20px;cursor:pointer;line-height:1;";
    close.onclick = hideOverlay;
    head.appendChild(title);
    head.appendChild(close);
    list = document.createElement("div");
    modal.appendChild(head);
    modal.appendChild(list);
    overlay.appendChild(modal);
    document.body.appendChild(overlay);
  }

  function hideOverlay() {
    if (!overlay) return;
    overlay.parentNode.removeChild(overlay);
    overlay = null;
    list = null;
  }

  function removeEntry(id) {
    var prev = document.getElementById(id);
    if (prev) {
      prev.parentNode.removeChild(prev);
      // Nothing left to report -- take the whole overlay down.
      if (list && list.children.length === 0) hideOverlay();
    }
  }

  function showError(label, message, replaceId) {
    ensureOverlay();
    if (replaceId) {
      var prev = document.getElementById(replaceId);
      if (prev) prev.parentNode.removeChild(prev);
    }
    if (list.children.length >= 20) list.removeChild(list.firstChild);
    var entry = document.createElement("pre");
    if (replaceId) entry.id = replaceId;
    entry.style.cssText =
      "white-space:pre-wrap;word-break:break-word;margin:10px 0 0;" +
      "padding:10px;background:#2a2a2c;border-radius:6px;";
    entry.textContent = "[" + label + "] " + message;
    list.appendChild(entry);
  }

  // No "development" badge here any more. The CHROME draws it (scaffold.js,
  // .wps-env), from the hostname, and having both produced two overlapping
  // pills on every dev-served page -- an orange one from the chrome and a
  // dark one from here. One rule, one place, and the surviving one is styled
  // with the product rather than as a raw injected div.

  // Browser-side errors -> overlay (and still the DevTools console).
  window.addEventListener("error", function (e) {
    var where = e.filename ? "\\n" + e.filename + ":" + e.lineno : "";
    showError("runtime", (e.message || "Unknown error") + where);
  });
  window.addEventListener("unhandledrejection", function (e) {
    showError("promise", String(e.reason));
  });
  var _consoleError = console.error;
  console.error = function () {
    _consoleError.apply(console, arguments);
    showError("console", Array.prototype.slice.call(arguments).join(" "));
  };

  // Live reload + compile errors pushed by the dev server over SSE.
  // Consecutive connection failures mean the dev server itself is gone
  // (terminal exited, Ctrl+C) -- surface that in the overlay too.
  var failures = 0;

  function connect() {
    var es = new EventSource("/_workpeg_reload");
    es.onopen = function () {
      failures = 0;
      removeEntry("_workpeg-server-error");
    };
    es.onmessage = function (ev) {
      if (ev.data === "reload") { location.reload(); return; }
      var msg;
      try { msg = JSON.parse(ev.data); } catch (err) { return; }
      if (msg.type === "error") {
        showError("compile", msg.message, "_workpeg-compile-error");
      }
    };
    es.onerror = function () {
      es.close();
      failures += 1;
      // One failure can be a transient blip; two in a row (~2s) means
      // the server is genuinely unreachable.
      if (failures >= 2) {
        showError(
          "server",
          "Dev server unreachable \\u2014 terminal exited or server " +
            "stopped. Retrying every second...",
          "_workpeg-server-error"
        );
      }
      setTimeout(connect, 1000);
    };
  }
  connect();
})();
"""


def _add_reload_tag(content: bytes) -> bytes:
    """A page with the dev script's tag before ``</body>``, or at the end
    when it has none."""
    if b"</body>" in content:
        return content.replace(b"</body>", _RELOAD_TAG + b"</body>", 1)
    return content + _RELOAD_TAG


def _is_spa_route(path: str) -> bool:
    """True when *path* looks like an SPA route rather than a static asset.

    An SPA route has no file extension (``/about``) or an HTML extension
    (``/about.html``). Paths that end with ``.js``, ``.css``, etc. are
    considered asset requests and should 404 normally.
    """
    _, ext = os.path.splitext(path)
    return not ext or ext.lower() in (".html", ".htm")


def _make_handler(directory: str) -> type:
    """Return a plain static-file handler rooted at *directory*."""

    abs_dir = str(Path(directory).resolve())

    class Handler(_SilentHandler):
        def __init__(self, *args: object, **kwargs: object) -> None:
            super().__init__(*args, directory=abs_dir, **kwargs)

        def do_GET(self) -> None:  # type: ignore[override]
            clean = self.path.split("?")[0].split("#")[0]
            fs_path = self.translate_path(clean)

            # SPA fallback: serve index.html for paths that have no matching
            # file but look like client-side routes (no file extension).
            if not os.path.isfile(fs_path) and _is_spa_route(clean):
                index = os.path.join(abs_dir, "index.html")
                if os.path.isfile(index):
                    self.path = "/index.html"

            super().do_GET()

    return Handler


def _make_reload_handler(
    directory: str,
    site=None,
    domain: "str | None" = None,
) -> tuple[type, Callable[..., None]]:
    """
    Return ``(HandlerClass, broadcast)`` for live-reload serving.

    With *site*, a :class:`workpeg.ui.devsite.DevSite`, and *domain*, the
    name it is served at, the handler is a dev page's: it serves only what
    the site says the last build wrote, to requests that name *domain*.

    ``broadcast()`` sends a reload event to every open SSE connection so the
    browser calls ``location.reload()``.  ``broadcast(error="...")`` instead
    pushes an error event that the injected dev overlay displays; the error
    is also replayed to clients that connect later, so a manual refresh
    while the build is broken still shows it.  A subsequent plain
    ``broadcast()`` clears the sticky error.
    """
    abs_dir = str(Path(directory).resolve())

    _clients: set[queue.Queue[str]] = set()
    _lock = threading.Lock()
    _last_error: "list[str | None]" = [None]

    def broadcast(error: "str | None" = None) -> None:
        if error is None:
            data = "reload"
        else:
            data = json.dumps({"type": "error", "message": error})
        with _lock:
            _last_error[0] = None if error is None else data
            for q in list(_clients):
                try:
                    q.put_nowait(data)
                except queue.Full:
                    pass

    class ReloadHandler(_SilentHandler):
        def __init__(self, *args: object, **kwargs: object) -> None:
            super().__init__(*args, directory=abs_dir, **kwargs)

        def do_GET(self) -> None:  # type: ignore[override]
            # Live-reload SSE stream.
            if self.path.split("?")[0] == "/_workpeg_reload":
                self._serve_sse()
                return

            clean = self.path.split("?")[0].split("#")[0]

            # The dev script, ahead of the disk: it is not a file in the dist,
            # and a file there with its name must not stand in for it.
            if clean == _RELOAD_SCRIPT_PATH:
                self._serve_reload_script()
                return

            fs_path = self.translate_path(clean)

            # Existing HTML file → add the dev script's tag and serve.
            if os.path.isfile(fs_path) and (
                clean in ("/", "") or clean.endswith(".html")
            ):
                self._serve_html(fs_path)
                return

            # SPA fallback: unknown path that looks like a client-side route →
            # serve index.html (with the dev script's tag added).
            if not os.path.isfile(fs_path) and _is_spa_route(clean):
                index = os.path.join(abs_dir, "index.html")
                if os.path.isfile(index):
                    self._serve_html(index)
                    return

            super().do_GET()

        # ---------------------------------------------------------------- SSE

        def _serve_sse(self) -> None:
            self.send_response(200)
            self.send_header("Content-Type", "text/event-stream")
            self.send_header("Cache-Control", "no-cache")
            self.send_header("Connection", "keep-alive")
            self.end_headers()

            q: queue.Queue[str] = queue.Queue(maxsize=4)
            with _lock:
                _clients.add(q)
                # Replay the current compile error to late subscribers so a
                # manual refresh while the build is broken still shows it.
                if _last_error[0] is not None:
                    q.put_nowait(_last_error[0])
            try:
                while True:
                    try:
                        msg = q.get(timeout=1)
                        self.wfile.write(f"data: {msg}\n\n".encode())
                        self.wfile.flush()
                    except queue.Empty:
                        # Keepalive comment — keeps the connection alive through proxies.
                        self.wfile.write(b": keepalive\n\n")
                        self.wfile.flush()
            except Exception:
                pass
            finally:
                with _lock:
                    _clients.discard(q)

        # ---------------------------------------------------------- dev script

        def _serve_reload_script(self) -> None:
            self.send_response(200)
            self.send_header("Content-Type", "text/javascript; charset=utf-8")
            self.send_header("Content-Length", str(len(_RELOAD_SCRIPT)))
            self.send_header("Cache-Control", "no-cache")
            self.end_headers()
            self.wfile.write(_RELOAD_SCRIPT)

        # --------------------------------------------------------------- HTML

        def _serve_html(self, fs_path: str) -> None:
            try:
                content = _add_reload_tag(Path(fs_path).read_bytes())
                self.send_response(200)
                self.send_header("Content-Type", "text/html; charset=utf-8")
                self.send_header("Content-Length", str(len(content)))
                self.send_header("Cache-Control", "no-cache")
                self.end_headers()
                self.wfile.write(content)
            except Exception:
                self.send_error(500)

    if site is None:
        return ReloadHandler, broadcast
    if not domain:
        raise ValueError("dev mode's handler answers only at its domain")
    return _dev_handler(ReloadHandler, site, domain), broadcast


#: What a dev page's server adds to the build's script policy. A page's meta
#: cannot say ``frame-ancestors``, so the header is the only place it can go,
#: and without it any same-site page could frame this one, whose session
#: cookies still ride, and steer a click.
FRAME_ANCESTORS = "; frame-ancestors 'none'"


#: The referrer rule a dev page's answers carry. Not a stricter one:
#: Accounts recognises a sign-in from a dev page by the origin its referrer
#: names, which ``no-referrer`` or ``same-origin`` would leave out.
DEV_REFERRER_POLICY = "strict-origin-when-cross-origin"


def _dev_handler(base: type, site, domain: str) -> type:
    """A dev page's handler (``serve --fake-cloud``): *base*,
    the reload handler, answering only
    what *site* (a :class:`workpeg.ui.devsite.DevSite`) says the last build
    wrote, to requests that name *domain*. The rules are devsite's; this is
    the HTTP.

    The browser sends this server the signed-in person's whole session, so
    every answer, an error included, carries the build's script policy with
    ``frame-ancestors 'none'``, ``X-Frame-Options: DENY``, ``nosniff`` and
    :data:`DEV_REFERRER_POLICY`; a request carrying ``Service-Worker`` is
    refused, so no worker outlives the server; an error never repeats what
    the request said; and what is written down is a request's method, path
    and status, never a header or a query."""
    from workpeg.ui.build import SCRIPT_POLICY
    from workpeg.ui.devsite import (
        HOST_REFUSED, SERVICE_WORKER_REFUSED, host_allowed)

    # On every answer, errors included: the page's policy, with framing
    # refused, which a meta cannot say; no file read as a type its own does
    # not say; and the referrer rule Accounts reads.
    headers = (
        ("Content-Security-Policy", SCRIPT_POLICY + FRAME_ANCESTORS),
        ("X-Frame-Options", "DENY"),
        ("X-Content-Type-Options", "nosniff"),
        ("Referrer-Policy", DEV_REFERRER_POLICY),
    )

    refused = HOST_REFUSED.format(domain=domain)

    class DevHandler(_site_handler(base, site, headers)):
        def parse_request(self) -> bool:
            # Here, before any method runs, so no route and no method is
            # answered to a request that names another server.
            if not super().parse_request():
                return False
            if not host_allowed(self.headers.get_all("Host") or [], domain):
                self.send_error(403, None, refused)
                return False
            # A browser sends this header, and only this one, when it fetches
            # a service worker's script. Whatever its value: a worker
            # installed here would go on answering for the page after the
            # server stops.
            if self.headers.get_all("Service-Worker"):
                self.send_error(403, None, SERVICE_WORKER_REFUSED)
                return False
            return True

        def send_error(self, code, message=None, explain=None) -> None:
            # The standard library's own words for an error can quote the
            # request line, and a request line can carry a cookie behind a
            # bare CR. The status's own phrase instead; the words this
            # handler passes as *explain* are fixed.
            super().send_error(code, None, explain)

        def log_request(self, code="-", size="-") -> None:
            # The method and path, without the query, and the status. Never
            # a header, so never a cookie, and never the raw line, which is
            # where a header smuggled behind a bare CR would be.
            status = getattr(code, "value", code)
            if not self.command:
                line = f"(a request line it could not read) {status}"
            else:
                path = self.path.split("?", 1)[0].split("#", 1)[0]
                if not path.isprintable():
                    path = ascii(path)
                line = f"{self.command} {path} {status}"
            sys.stderr.write(f"  {line}\n")

    return DevHandler


def _site_handler(base: type, site, headers) -> type:
    """*base*, the reload handler, answering GET and HEAD with only what
    *site* says the last build wrote, and sending *headers*, ``(name,
    value)`` pairs, on every answer, errors included."""

    class SiteHandler(base):
        # An error is text. As HTML it would be a second page on the peg's
        # origin, with none of the page's metas.
        error_content_type = "text/plain; charset=utf-8"
        error_message_format = "%(code)d %(message)s\n\n%(explain)s\n"

        def end_headers(self) -> None:
            for name, value in headers:
                self.send_header(name, value)
            super().end_headers()

        def do_GET(self) -> None:  # type: ignore[override]
            self._answer(body=True)

        def do_HEAD(self) -> None:  # type: ignore[override]
            self._answer(body=False)

        def _answer(self, body: bool) -> None:
            clean = self.path.split("?", 1)[0].split("#", 1)[0]
            if clean == "/_workpeg_reload":
                if body:
                    self._serve_sse()
                else:
                    self._send(b"", "text/event-stream", body, cache=False)
                return
            if clean == _RELOAD_SCRIPT_PATH:
                self._send(_RELOAD_SCRIPT, "text/javascript; charset=utf-8",
                           body, cache=False)
                return
            found = site.resolve(clean)
            try:
                content = None if found is None else found.read_bytes()
            except OSError:
                content = None
            if content is None:
                self.send_error(404)
            elif found == site.index:
                self._send(site.page(content), "text/html; charset=utf-8",
                           body, cache=False)
            else:
                self._send(content, self.guess_type(str(found)), body)

        def _send(self, content: bytes, kind: str, body: bool,
                  cache: bool = True) -> None:
            self.send_response(200)
            self.send_header("Content-Type", kind)
            self.send_header("Content-Length", str(len(content)))
            if not cache:
                self.send_header("Cache-Control", "no-cache")
            self.end_headers()
            if body:
                self.wfile.write(content)

    return SiteHandler


def _format_url(host: str, port: int, https: bool) -> str:
    """Build a display URL, hiding the default port for the scheme."""
    scheme = "https" if https else "http"
    default = 443 if https else 80
    if port == default:
        return f"{scheme}://{host}"
    return f"{scheme}://{host}:{port}"


def find_free_port(start: int = 8080, host: str = "") -> int:
    """Return the first available TCP port starting from *start*.

    Each port is tried by binding it on *host*. The default, ``""``, tries
    every interface. A server that will bind one address passes it, so even
    a try is made only there: dev mode serves on 127.0.0.1 and binds
    nothing anywhere else."""
    for port in range(start, start + 20):
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            try:
                s.bind((host, port))
                return port
            except OSError:
                continue
    raise RuntimeError(
        f"No free port found in range {start}–{start + 19}. "
        "Pass an explicit --port value."
    )


def _bind_host() -> str:
    """Interface the dev server listens on. Localhost by default, so the app,
    live-reload endpoint and error overlay aren't exposed to the whole LAN; set
    ``WORKPEG_BIND_HOST=0.0.0.0`` to reach it from another device on purpose."""
    return os.environ.get("WORKPEG_BIND_HOST", "127.0.0.1").strip() or "127.0.0.1"


def _bind_tcp_server(server_cls, port: int, handler, bind_host: "str | None" = None):
    """Build *server_cls* bound to ``(bind_host or _bind_host(), port)``, turning
    a failed bind into a clear :class:`ServeError` (never a raw traceback).

    macOS quirk worth calling out: a non-root process may bind a privileged
    port (<1024) on *all* interfaces (``0.0.0.0``) but NOT on a single address
    like ``127.0.0.1`` — so loopback-binding 443 fails with EACCES unless run
    as root. That's why the message points at sudo / a high port / the
    ``WORKPEG_BIND_HOST`` opt-out rather than just failing."""
    host = bind_host or _bind_host()
    try:
        return server_cls((host, port), handler)
    except PermissionError as exc:
        if port < 1024:
            raise ServeError(
                f"Can't bind {host}:{port} — port {port} is privileged (<1024). "
                f"Re-run with sudo, use a high port (drop --port to auto-pick, "
                f"or e.g. --port 8443), or set WORKPEG_BIND_HOST=0.0.0.0 to bind "
                f"every interface (also reachable from the LAN)."
            ) from exc
        raise ServeError(f"Not permitted to bind {host}:{port}.") from exc
    except OSError as exc:
        if exc.errno == errno.EADDRINUSE:
            raise ServeError(
                f"{host}:{port} is already in use — stop whatever is using it, "
                f"or pass a different --port."
            ) from exc
        raise


def _create_server(
    directory: str, port: int, bind_host: "str | None" = None,
    tls: "ssl.SSLContext | None" = None,
) -> tuple[socketserver.BaseServer, str]:
    abs_dir = str(Path(directory).resolve())
    server = _bind_tcp_server(
        _server_class(_ReusingTCPServer, tls), port, _make_handler(abs_dir),
        bind_host)
    return server, f"http://localhost:{port}"


def _resolve_build_source(watch_source: str) -> str:
    """Return the ``.py`` file to compile for *watch_source*.

    When *watch_source* is a project directory, the build source is
    ``main.py`` inside that directory; otherwise it is the path itself.
    """
    ws = Path(watch_source)
    if ws.is_dir():
        return str(ws / "main.py")
    return str(ws)


def _plain_build(
    build_source: str, directory: str, peg_namespace: "str | None"
) -> Callable[[], None]:
    """Plain serve's build of *build_source* into *directory*, as a save
    runs it."""

    def _serve_build() -> None:
        from workpeg.ui.build import build_ui

        # Keep the dev-chosen namespace on every recompile, else an edit
        # would revert the <meta name="peg-namespace"> to the derived slug.
        build_ui(build_source, directory, peg_namespace=peg_namespace,
                 bundle_icons=True)

    return _serve_build


def _make_watcher_callback(
    watch_source: str,
    directory: str,
    broadcast: Callable[..., None],
    peg_namespace: "str | None" = None,
    rebuild: "Callable[[], object] | None" = None,
) -> Callable[[], None]:
    """What a save does: build, then reload the page or show the error.

    *rebuild* is the build to run. Without one it is plain serve's; dev
    mode passes its own, which builds as a release does.
    """
    run_build = rebuild or _plain_build(
        _resolve_build_source(watch_source), directory, peg_namespace)

    def _on_change() -> None:
        from workpeg.ui.compiler.ast_parser import UnsupportedSyntaxError

        from workpeg.terminal import shown_lines

        # The terminal gets the error's words escaped, since they quote the
        # developer's file names and source; the page's overlay, which shows
        # them as text, gets them as they are.
        try:
            run_build()
            broadcast()
        except (UnsupportedSyntaxError, SyntaxError) as e:
            # Both carry the offending file name: UnsupportedSyntaxError
            # via its file attribute, SyntaxError via ast.parse(filename=).
            print(f"\n  [workpeg] Compile error: {shown_lines(e)}",
                  flush=True)
            broadcast(error=f"Compile error: {e}")
        except Exception as e:
            print(f"\n  [workpeg] Error: {shown_lines(e)}", flush=True)
            broadcast(error=str(e))

    return _on_change


def _watching_server(
    directory: str,
    port: int,
    watch_source: "str | Path",
    peg_namespace: "str | None",
    bind_host: "str | None",
    tls: "ssl.SSLContext | None" = None,
) -> socketserver.BaseServer:
    """Bind the reload server on *directory* and start its watcher. With
    *tls* it speaks TLS, to this computer only. A dev page (``serve
    --fake-cloud``) has a server of its own
    (:mod:`workpeg.ui.devserve`)."""
    abs_dir = str(Path(directory).resolve())
    handler_cls, broadcast = _make_reload_handler(abs_dir)
    server = _bind_tcp_server(
        _server_class(_ReloadTCPServer, tls), port, handler_cls, bind_host)

    from workpeg.ui.watcher import FileWatcher

    FileWatcher(
        str(watch_source),
        _make_watcher_callback(
            str(watch_source), abs_dir, broadcast, peg_namespace),
    ).start()
    return server


def serve_background(
    directory: str,
    port: int = 0,
    watch_source: "str | Path | None" = None,
    ssl_cert: "str | None" = None,
    ssl_key: "str | None" = None,
    url_host: str = "localhost",
    peg_namespace: "str | None" = None,
    bind_host: "str | None" = None,
) -> tuple[str, socketserver.BaseServer]:
    """
    Start an HTTP file server in a background daemon thread.

    When *watch_source* is given the server:

    - Adds a dev script (live-reload + error overlay) to every HTML response,
      as a tag naming ``/_workpeg_reload.js``, which it serves from memory.
      Compile errors, uncaught runtime errors, unhandled promise rejections,
      and console.error calls appear in a dismissible modal. Built dist/ files
      are never modified — the overlay exists only while serving.
    - Exposes ``GET /_workpeg_reload`` as a Server-Sent Events endpoint.
    - Recompiles *watch_source* on every mtime change detected by
      :class:`~workpeg.ui.watcher.FileWatcher`, broadcasting a reload event
      on success and an error event on compile failure.

    When *ssl_cert* and *ssl_key* are given the server speaks HTTPS, to
    this computer only (see :class:`LoopbackTLSServer`), and *url_host*
    customises the host shown in the returned URL.

    Returns ``(url, server)``. Call ``server.shutdown()`` to stop.
    Intended for programmatic and test use.
    """
    https = bool(ssl_cert and ssl_key)
    tls = _tls_context(ssl_cert, ssl_key) if https else None
    if port == 0:
        # Tried where the server will bind, when it is told where. Without
        # a bind_host the try stays on every interface, as it always was.
        port = find_free_port(host=bind_host or "")

    if watch_source is not None:
        server: socketserver.BaseServer = _watching_server(
            directory, port, watch_source, peg_namespace, bind_host, tls)
    else:
        server, _ = _create_server(directory, port, bind_host, tls)

    t = threading.Thread(target=server.serve_forever, daemon=True)
    t.start()
    return _format_url(url_host, port, https), server


def serve_blocking(
    directory: str,
    port: int = 0,
    watch_source: "str | Path | None" = None,
    ssl_cert: "str | None" = None,
    ssl_key: "str | None" = None,
    url_host: str = "localhost",
    peg_namespace: "str | None" = None,
    bind_host: "str | None" = None,
) -> None:
    """
    Start an HTTP file server in the calling thread and block until Ctrl+C.

    When *watch_source* is given the server adds a live-reload script and
    recompiles + refreshes the browser on every file change.  When *ssl_cert*
    and *ssl_key* are given the server speaks HTTPS, to this computer only
    (:class:`LoopbackTLSServer`); *url_host* customises the displayed host.
    *peg_namespace* overrides the Peg namespace baked into each recompile
    (``--peg-namespace``), so the app runs locally as that Peg (CDN logo,
    ``workpeg.*`` header, …).

    A dev page (``serve --fake-cloud``) does not come here: it
    has its own server, on port 443 only (:mod:`workpeg.ui.devserve`).

    Intended for CLI use (``workpeg ui serve`` and ``workpeg ui new``).
    """
    https = bool(ssl_cert and ssl_key)
    tls = _tls_context(ssl_cert, ssl_key) if https else None
    if port == 0:
        # Tried where the server will bind, when it is told where. Without
        # a bind_host the try stays on every interface, as it always was.
        port = find_free_port(host=bind_host or "")

    url = _format_url(url_host, port, https)

    if watch_source is not None:
        server: socketserver.BaseServer = _watching_server(
            directory, port, watch_source, peg_namespace, bind_host, tls)

        ws_path = Path(str(watch_source))
        from workpeg.terminal import shown

        watch_label = shown(ws_path if ws_path.is_dir() else ws_path.name)
        print(f"\n  Serving  →  {url}")
        print(f"  Watching →  {watch_label}")
        print("  Stop     →  Ctrl+C\n")
    else:
        server, _ = _create_server(directory, port, bind_host, tls)
        print(f"\n  Serving  →  {url}")
        print("  Stop     →  Ctrl+C\n")

    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
        print("\nStopped.")
